    /// <summary>
    /// Deletes all information about a language pack in the current localization target. The language pack which is currently in use (including base language pack) or is being synchronized can't be deleted.
    /// Can be called before authorization
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> DeleteLanguagePackAsync(string languagePackId = default)
    {

           using var activity =  StartCallActivity("DeleteLanguagePackAsync", typeof(DeleteLanguagePack).FullName ?? "DeleteLanguagePackAsync");

           try
           {
             return client.DeleteLanguagePackAsync(languagePackId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
